interface.definition:
a!localVariables(
  local!showInterview: a!refreshVariable(
    value: repeat(count(ri!interviews),true),
    refreshOnReferencedVarChange: false
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Request Interviews",
    labelColor: "SECONDARY",
    isCollapsible: true,
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: #"SYSTEM_SYSRULES_cardLayout"(
              style: "ACCENT",
              contents: {
                #"SYSTEM_SYSRULES_richTextDisplayField"(
                  labelPosition: "COLLAPSED",
                  value: {
                    #"SYSTEM_SYSRULES_richTextIcon"(
                      icon: "plus",
                      linkStyle: "STANDALONE",
                      color: "ACCENT",
                      size: "STANDARD"
                    ),
                    #"SYSTEM_SYSRULES_richTextItem_v1"(
                      text: " New Interview",
                      linkStyle: "STANDALONE",
                      color: "STANDARD",
                      size: "MEDIUM",
                      style: "STRONG"
                    )
                  },
                  align: "CENTER"
                )
              },
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                value: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3884277"(),
                saveInto: {
                  a!save(
                    ri!interviews,
                    insert(ri!interviews, save!value, 1)
                  ),
                  a!save(
                    local!showInterview,
                    insert(local!showInterview, true, 1)
                  )
                }
              ),
              height: "AUTO"
            ),
            width: "NARROW"
          )
        }
      ),
      #"SYSTEM_SYSRULES_forEach"(
        items: ri!interviews,
        expression: #"SYSTEM_SYSRULES_sectionLayout_v1"(
          marginBelow: if(
            local!showInterview[fv!index],
            "STANDARD",
            "LESS"
          ),
          contents: {
            #"SYSTEM_SYSRULES_cardLayout"(
              contents: #"SYSTEM_SYSRULES_sideBySideLayout"(
                items: {
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: if(
                            index(local!showInterview,fv!index,toboolean(null)) = true,
                            "chevron-down",
                            "chevron-right"
                          ),
                          link: #"SYSTEM_SYSRULES_dynamicLink"(
                            saveInto: {
                              a!save(
                                local!showInterview[fv!index],
                                not(index(local!showInterview, fv!index))
                              )
                            }
                          ),
                          linkStyle: "STANDALONE",
                          size: "MEDIUM"
                        ),
                        char(32),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: "Interview",
                          size: "MEDIUM",
                          style: "STRONG"
                        )
                      }
                    )
                  ),
                  #"SYSTEM_SYSRULES_sideBySideItem"(
                    item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                      value: #"SYSTEM_SYSRULES_richTextIcon"(
                        icon: "remove",
                        caption: "Delete Interview",
                        link: #"SYSTEM_SYSRULES_dynamicLink"(
                          saveInto: {
                            /*if interview is already saved in the DB, mark as inactive, else remove*/
                            if(
                              #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(property(fv!item, "interviewId", null)),
                              {
                                a!save(
                                  local!showInterview,
                                  remove(local!showInterview, fv!index)
                                ),
                                a!save(
                                  ri!interviews,
                                  remove(ri!interviews, fv!index)
                                )
                              },
                              {
                                a!save(fv!item.isActive, false),
                                a!save(local!showInterview[fv!index], false)
                              }
                            )
                          }
                        ),
                        linkStyle: "STANDALONE",
                        color: "NEGATIVE",
                        size: "MEDIUM"
                      ),
                      align: "RIGHT"
                    )
                  )
                }
              ),
              link: #"SYSTEM_SYSRULES_dynamicLink"(
                saveInto: {
                  a!save(
                    local!showInterview[fv!index],
                    not(index(local!showInterview, fv!index))
                  )
                }
              ),
              showWhen: property(fv!item, "isActive", false),
              style: "STANDARD",
              padding: "EVEN_LESS"
            ),
            #"_a-0000e6cf-8b0b-8000-9c00-011c48011c48_3748740"(
              interview: fv!item,
              showWhen: local!showInterview[fv!index]
            )
          }
        )
      )
    }
  )
)
